//! Raw native named presence and own descriptors preserve actual attributes.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_raw_inspection_native_in_and_own_presence_are_live(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,key='x\ud800B';if(key in d||Object.hasOwn(d,key)||Object.prototype.hasOwnProperty.call(d,key)||Object.prototype.propertyIsEnumerable.call(d,key))throw 'absent';n.setAttributeNS(null,'data-x\ud800-b','');if(!(key in d)||!Object.hasOwn(d,key)||!Object.prototype.hasOwnProperty.call(d,key)||!Object.prototype.propertyIsEnumerable.call(d,key))throw 'empty native attribute presence';n.removeAttributeNS(null,'data-x\ud800-b');if(key in d||Object.hasOwn(d,key)||Object.prototype.propertyIsEnumerable.call(d,key))throw 'live deletion';"#);}

#[test]
fn dataset_raw_inspection_descriptor_is_native_data_and_live_snapshot(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,key='x\udfff';n.setAttributeNS(null,'data-x\udfff','old\ud800');var a=Object.getOwnPropertyDescriptor(d,key);if(!a||a.value!=='old\ud800'||!a.writable||!a.enumerable||!a.configurable||Object.hasOwn(a,'get')||Object.hasOwn(a,'set'))throw 'native data descriptor';n.setAttributeNS(null,'data-x\udfff','new');var b=Object.getOwnPropertyDescriptor(d,key);if(b===a||a.value!=='old\ud800'||b.value!=='new')throw 'live native descriptor snapshot';n.removeAttributeNS(null,'data-x\udfff');if(Object.getOwnPropertyDescriptor(d,key)!==undefined)throw 'removed native descriptor';"#);}

#[test]
fn dataset_raw_inspection_own_queries_never_invoke_prototype_getter(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,key='x\ud800',p=DOMStringMap.prototype,hits=0;Object.defineProperty(p,key,{get:function(){hits++;throw 'getter must not run';},enumerable:true,configurable:true});if(!(key in d)||Object.hasOwn(d,key)||Object.prototype.hasOwnProperty.call(d,key)||Object.prototype.propertyIsEnumerable.call(d,key)||Object.getOwnPropertyDescriptor(d,key)!==undefined||hits)throw 'inherited presence is not own';n.setAttributeNS(null,'data-x\ud800','native');if(!(key in d)||!Object.hasOwn(d,key)||!Object.prototype.propertyIsEnumerable.call(d,key)||Object.getOwnPropertyDescriptor(d,key).value!=='native'||hits)throw 'native override without author getter';delete p[key];n.removeAttributeNS(null,'data-x\ud800');if(key in d)throw 'prototype/native removal';"#);}

#[test]
fn dataset_raw_inspection_namespace_ascii_and_projection_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset;n.setAttributeNS(null,'data-x\ud800-b','raw');n.setAttributeNS(null,'data-x\ufffd-b','scalar');n.setAttributeNS(null,'data-UP\ud800','excluded');if(!Object.hasOwn(d,'x\ud800B')||!Object.hasOwn(d,'x\ufffdB')||Object.hasOwn(d,'x\ud800-b')||Object.hasOwn(d,'UP\ud800')||Object.getOwnPropertyDescriptor(d,'x\ud800B').value!=='raw'||Object.getOwnPropertyDescriptor(d,'x\ufffdB').value!=='scalar')throw 'exact membership';}var n=document.getElementById('target');n.setAttributeNS('urn:foreign','p:data-n\ud800','foreign');if(Object.hasOwn(n.dataset,'n\ud800')||'n\ud800' in n.dataset||Object.getOwnPropertyDescriptor(n.dataset,'n\ud800'))throw 'namespace excluded';"#);}

#[test]
fn dataset_raw_inspection_key_conversion_order_abrupt_identity_and_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,calls=0,key={toString:function(){calls++;return 'x\ud800';}};n.setAttributeNS(null,'data-x\ud800','native');if(!(key in d)||calls!==1||!Object.hasOwn(d,key)||calls!==2||Object.getOwnPropertyDescriptor(d,key).value!=='native'||calls!==3)throw 'once key binding';var thrown={};for(var mode of [0,1,2]){var bad={toString:function(){throw thrown;}},seen=false;try{if(mode===0)bad in d;else if(mode===1)Object.hasOwn(d,bad);else Object.getOwnPropertyDescriptor(d,bad);}catch(e){seen=e===thrown;}if(!seen)throw 'abrupt identity';}if(!Object.hasOwn(d,'x\ud800'))throw 'recovery';"#);}

#[test]
fn dataset_raw_inspection_presence_needs_no_native_value_copy_and_refusal_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;n.setAttributeNS(null,'data-x\ud800','value');"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let retained=p.state.retained;p.begin_job();p.state.copy_work=0;p.state.retained=p.state.retained_limit;p.runtime.execute(r#"if(!('x\ud800' in d)||!Object.hasOwn(d,'x\ud800')||!Object.prototype.propertyIsEnumerable.call(d,'x\ud800'))throw 'borrowed presence';"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();p.begin_job();p.state.copy_work=0;let error=p.runtime.execute(r#"Object.getOwnPropertyDescriptor(d,'x\ud800');"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(!error.is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained=retained;run(&mut d,&mut f,&mut p,r#"if(Object.getOwnPropertyDescriptor(d,'x\ud800').value!=='value')throw 'recovered native descriptor';"#);}
